"""RoboPaint stroke-copy controller. Uses only public RGB/depth/proprio and actions."""
import sys, json, time, math
from pathlib import Path
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
import numpy as np
from PIL import Image
OUT=Path('/app/output')
class Painter:
 def __init__(self):
  self.r=Robot(); self.obs=self.r.get_obs(cameras=[]); self.pos=np.array(self.obs.meta['proprio']['now'][7:10]); self.quat=np.array([0.,1.,0.,0.]); self.rows=[]
 def flush(self,cameras=[]):
  if not self.rows:return
  a=np.array(self.rows); self.rows=[]
  for start in range(0,len(a),180):
   chunk=a[start:start+180]; before=self.r.status()
   try: res=self.r.submit('ee_pose',chunk,dt=.05,cameras=cameras,video='none')
   except Exception:
    st=self.r.wait_ready();
    if st['calls']<=before['calls']: res=self.r.submit('ee_pose',chunk,dt=.05,cameras=cameras,video='none')
    else: res=self.r.get_obs(cameras=cameras)
   with open(OUT/'motion_log.jsonl','a') as f:f.write(json.dumps({'n':len(chunk),'meta':res.meta})+'\n')
   if res.stopped:raise RuntimeError('Stopped call')
  self.obs=res
 def move(self,p,speed=.08,hold=0):
  p=np.array(p,float); n=max(1,int(np.ceil(np.linalg.norm(p-self.pos)/speed/.05)))
  for t in np.linspace(0,1,n+1)[1:]:self.rows.append(np.r_[self.pos+(p-self.pos)*t,self.quat])
  self.rows.extend([np.r_[p,self.quat]]*int(round(hold/.05)));self.pos=p
 def see(self,name):
  self.flush(); o=self.r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True);o.save(str(OUT/name));return o
if __name__=='__main__':
 p=Painter();p.move([-.3,0,.16],hold=.5);p.see('clear')
