"""Compare target colour regions with a rectified public camera image."""
import numpy as np,json,sys
from scipy import ndimage as ndi
from scipy.cluster.vq import kmeans2
from PIL import Image
OUT='/app/output/'
def rectified(path):
 im=np.asarray(Image.open(path),dtype=float);t=np.arange(1024);px=512+((t+.5)-512)*.00022186*2344.588379/.5998;yy,xx=np.meshgrid(px,px,indexing='ij')
 return np.stack([ndi.map_coordinates(im[:,:,i],[yy,xx],order=1) for i in range(3)],axis=-1)
def diagnose(path):
 im=rectified(path);lab=np.load(OUT+'labels.npy');spec=json.load(open(OUT+'spec.json'));palette=np.vstack([np.array([p['rgb'] for p in spec['static']['wells']['wells']])*255,[248,244,236]])
 centers=[]
 for c in range(11):
  mask=ndi.binary_erosion(lab==c,iterations=6)
  centers.append(np.median(im[mask],axis=0))
 centers=np.array(centers);nearest=np.argmin(np.linalg.norm(im[:,:,None,:]-centers[None,None,:,:],axis=-1),axis=-1)
 np.save(OUT+'observed_labels.npy',nearest)
 est=palette[nearest].astype(np.uint8);Image.fromarray(est).save(OUT+'observed_flat.png');Image.fromarray(im.astype(np.uint8)).save(OUT+'rectified.png')
 print('prototypes',centers.tolist())
 for c in range(11):
  a=nearest==c;b=lab==c; print(c,'target',b.sum(),'seen',a.sum(),'IoU',round((a&b).sum()/max(1,(a|b).sum()),3),'miss',int((b&~a).sum()),'excess',int((a&~b).sum()))
 return nearest
if __name__=='__main__':diagnose(sys.argv[1])
